const jobs = [
  { name: 'A', start: 1, finish: 4 },
  { name: 'B', start: 3, finish: 5 },
  { name: 'C', start: 0, finish: 6 },
  { name: 'D', start: 5, finish: 7 },
  { name: 'E', start: 3, finish: 9 },
  { name: 'F', start: 5, finish: 9 },
  { name: 'G', start: 6, finish: 10 },
  { name: 'H', start: 8, finish: 11 },
  { name: 'I', start: 8, finish: 12 },
  { name: 'J', start: 2, finish: 14 },
  { name: 'K', start: 12, finish: 16 },
];
function select(jobs, key) {
  const sorted = [...jobs].sort((a, b) => a[key] - b[key]);
  const chosen = [];
  let lastFinish = -Infinity;
  for (const job of sorted) {
    if (job.start >= lastFinish) { chosen.push(job.name); lastFinish = job.finish; }
  }
  return chosen;
}
const byFinish = select(jobs, 'finish');
const byStart = select(jobs, 'start');
console.log('by finish:', byFinish.join(' '), '=>', byFinish.length);
console.log('by start :', byStart.join(' '), '=>', byStart.length);
console.log('finish-time order is optimal?', byFinish.length === 4);
